import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { Group, Mesh, PlaneGeometry } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: ThreePlaneGeometry } = ctx.THREE;

  // Root container
  const root = new ThreeGroup();
  root.position.set(3.2, -0.3, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // Geometry and material (placeholder)
  const geometry = new ThreePlaneGeometry(7, 6); // size arbitrary, can be adjusted later
  const material = new MeshBasicNodeMaterial();
  const plane = new ThreeMesh(geometry, material);
  plane.scale.set(1, 1, 1);
  root.add(plane);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // GSAP timelines storage
  const timelines = [];

  // Hover effect: rise‑in (subtle lift of 0.15 units)
  const hoverEnter = () => {
    const tl = gsap.to(plane.position, {
      y: plane.position.y + 0.15,
      duration: 0.5,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };
  const hoverLeave = () => {
    const tl = gsap.to(plane.position, {
      y: plane.position.y - 0.15,
      duration: 0.5,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  // Click effect: emit navigation event
  const onClick = () => {
    ctx.emit('hub-journal.select', {});
  };

  // Attach handlers
  root.userData.handlers = {
    hoverEnter,
    hoverLeave,
    click: onClick,
  };

  // Cleanup
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    timelines.length = 0;
    geometry.dispose();
    if (material.map) material.map.dispose();
    material.dispose();
    root.traverse((child) => {
      if (child.userData && child.userData.handlers) delete child.userData.handlers;
    });
  };

  // Apply cinematic primitives if any (none in this spec)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        const p = ctx.primitives[prim.name](root, prim.params);
        if (p && p.cleanup) {
          const origCleanup = root.userData.cleanup;
          root.userData.cleanup = () => {
            p.cleanup();
            if (origCleanup) origCleanup();
          };
        }
      }
    }
  }

  return root;
}
